import React, { Suspense, lazy } from 'react';
import { useData } from '../../context/DataContext';
import styles from './HomePage.module.css';

// Adjust imports to handle named exports
const Slider = lazy(() => import('./Slider/Slider').then(module => ({ default: module.Slider })));
const CouponsCard = lazy(() => import('./CouponsCard/CouponsCard').then(module => ({ default: module.CouponsCard })));
const CashBack = lazy(() => import('./CashBack/CashBack').then(module => ({ default: module.CashBack })));
const CashDesc = lazy(() => import('./CashDesc/CashDesc').then(module => ({ default: module.CashDesc })));
const Deals = lazy(() => import('./Deals/Deals').then(module => ({ default: module.Deals })));
const FavoriteStore = lazy(() => import('./FavoriteStore/FavoriteStore'));
const TodayDeals = lazy(() => import('./TodayDeals/TodayDeals').then(module => ({ default: module.TodayDeals })));
const TopStore = lazy(() => import('./TopStore/TopStore'));

const Section = ({ title, children }) => (
  <section className={styles.section}>
    <h2>{title}</h2>
    <div className={styles.cardsGrid}>{children}</div>
  </section>
);

export const HomePage = () => {
  const { coupons = [], cashBacks = [], deals = [] } = useData();

  return (
    <div className={styles.homePage}>
      <Suspense fallback={<div>Loading...</div>}>
        <Slider />
        <Section title="The Best Coupons, Promo Codes & Cash Back Offers">
          {Array.isArray(coupons) && coupons.map((coupon) => (
            <CouponsCard key={coupon.id} {...coupon} />
          ))}
        </Section>
        <Section title="Cash Back Offers">
          {Array.isArray(cashBacks) && cashBacks.map((cashBack) => (
            <CashBack key={cashBack.id} percent={cashBack.percent} />
          ))}
        </Section>
        <Section title="Top Deals">
          {Array.isArray(deals) && deals.map((deal) => (
            <Deals key={deal.id} brand={deal.brand} title={deal.title} />
          ))}
        </Section>
        <Section title="Favorite Stores">
          {Array.isArray(cashBacks) && cashBacks.map((cashBack) => (
            <FavoriteStore key={cashBack.id} percent={cashBack.percent} />
          ))}
        </Section>
        <Section title="Today's Top Deals">
          {Array.isArray(deals) && deals.map((deal) => (
            <TodayDeals key={deal.id} promo="10%" title={deal.title} />
          ))}
        </Section>
        <Section title="Top Stores">
          {Array.isArray(cashBacks) && cashBacks.map((cashBack) => (
            <TopStore key={cashBack.id} percent={cashBack.percent} />
          ))}
        </Section>
        <Section title="Why Cash Back?">
          <CashDesc />
        </Section>
      </Suspense>
    </div>
  );
};
